practice.solution:
import re

GENERATIVE = {'write', 'draft', 'generate', 'summarize', 'summarise', 'translate', 'compose', 'rewrite', 'create'}
PREDICTIVE = {'classify', 'predict', 'detect', 'forecast', 'estimate', 'score', 'flag', 'rank'}

n = int(input())
counts = {'generative': 0, 'predictive': 0, 'hybrid': 0, 'unclear': 0}
for i in range(1, n + 1):
    words = set(re.findall(r'[a-z]+', input().lower()))
    gen = bool(words & GENERATIVE)
    pred = bool(words & PREDICTIVE)
    if gen and pred:
        label = 'hybrid'
    elif gen:
        label = 'generative'
    elif pred:
        label = 'predictive'
    else:
        label = 'unclear'
    counts[label] += 1
    print(f'{i}. {label}')
print(' '.join(f'{k}={v}' for k, v in counts.items()))
